1	/** Format integer cents as a US dollar string, e.g. 2400 → "$24". */
2	export function formatCents(cents: number): string {
3	  const dollars = cents / 100;
4	  const hasFraction = cents % 100 !== 0;
5	  return dollars.toLocaleString("en-US", {
6	    style: "currency",
7	    currency: "USD",
8	    minimumFractionDigits: hasFraction ? 2 : 0,
9	    maximumFractionDigits: 2,
10	  });
11	}
12	
13	/** Price summary for a block, e.g. "$24 / 30 min". */
14	export function formatBlockPrice(cents: number, minutes: number): string {
15	  return `${formatCents(cents)} / ${minutes} min`;
16	}
17	
18	/** Rating to one decimal, e.g. 4.9. */
19	export function formatRating(avg: number): string {
20	  return avg.toFixed(1);
21	}
